        "override and implement `onPlayFromSearch(String query, Bundle bundle)`.\n\n" +
        "Reference: https://developer.android.com/training/auto/audio/index.html#support_voice",
        Category.CORRECTNESS,
        6,
        Severity.WARNING,
        new Implementation(AndroidAutoDetector.class, Scope.JAVA_FILE_SCOPE)
    );

    @Override
    public List<Class<? extends org.jetbrains.uast.UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public void visitClass(JavaContext context, UClass node) {
        if (node.isInterface()) {
            return;
        }

        // Check for abstract using PsiClass modifiers
        PsiClass psiClass = node.getPsi();
        if (psiClass != null && psiClass.getModifierList() != null && psiClass.getModifierList().hasModifierProperty(com.intellij.psi.PsiModifier.ABSTRACT)) {
