        }

        boolean isCallback = context.extendsClass(node, "android.media.session.MediaSession.Callback", false)
                || context.extendsClass(node, "android.support.v4.media.session.MediaSessionCompat.Callback", false)
                || context.extendsClass(node, "androidx.media.session.MediaSessionCompat.Callback", false);

        if (!isCallback) {
            return;
        }

        boolean hasOnPlayFromSearch = false;
        for (UMethod method : node.getMethods()) {
            if ("onPlayFromSearch".equals(method.getName())) {
                List<UParameter> parameters = method.getUastParameters();
                if (parameters.size() == 2) {
                    PsiType type1 = parameters.get(0).getType();
                    PsiType type2 = parameters.get(1).getType();
                    if (type1 != null && type2 != null) {
                        String t1 = type1.getCanonicalText();
                        String t2 = type2.getCanonicalText();
                        if (t1.endsWith("String") && t2.endsWith("Bundle")) {
                            hasOnPlayFromSearch = true;
                            break;
                        }
                    }
                }
            }
        }

        if (!hasOnPlayFromSearch) {
            context.report(ISSUE, node, context.getNameLocation(node),
                "This class should override `onPlayFromSearch(String, Bundle)` to support Android Auto voice searches");
        }
    }
}
