        PsiClass psiClass = node.getJavaPsi();
        if (psiClass == null) {
            return;
        }

        if (psiClass.getModifierList() != null && psiClass.getModifierList().hasModifierProperty(PsiModifier.ABSTRACT)) {
            return;
        }

        boolean isCallback = context.getEvaluator().extendsClass(psiClass, "android.media.session.MediaSession.Callback", false)
                || context.getEvaluator().extendsClass(psiClass, "android.support.v4.media.session.MediaSessionCompat.Callback", false)
